#!/usr/bin/env python3
"""Converts nunicode's generated C tables into the checked-in Rust sources
under vendor/nunicode/src/tables/.

`just generate-nunicode-tables` runs it with the paths below.

Usage: gen_tables.py <nunicode dir> <output dir>
  <nunicode dir>: ../maplibre-native/vendor/nunicode
  <output dir>:   vendor/nunicode/src/tables

The MPH tables (G, VALUES_C, VALUES_I, COMBINED) become Rust arrays with the
C element types; integer literals that overflow the C type are wrapped the
way the C conversion does. The contraction function of _ducet_switch.c is
translated statement by statement (if/else-if tree and switch statements
kept as they are), not flattened.
"""

import os
import re
import sys

C_TO_RUST = {"int16_t": "i16", "uint16_t": "u16", "uint32_t": "u32", "uint8_t": "u8"}
BITS = {"int16_t": (16, True), "uint16_t": (16, False), "uint32_t": (32, False), "uint8_t": (8, False)}

ARRAY_RE = re.compile(r"const\s+(int16_t|uint16_t|uint32_t|uint8_t)\s+(\w+)\[\]\s*=\s*\{(.*?)\};", re.S)


def wrap(value, ctype):
    bits, signed = BITS[ctype]
    value &= (1 << bits) - 1
    if signed and value >= 1 << (bits - 1):
        value -= 1 << bits
    return value


def parse_int(token):
    token = token.strip()
    return int(token, 16) if token.lower().startswith(("0x", "-0x")) else int(token)


def arrays(text):
    out = []
    for ctype, name, body in ARRAY_RE.findall(text):
        body = re.sub(r"/\*.*?\*/", "", body, flags=re.S)
        values = [wrap(parse_int(t), ctype) for t in body.split(",") if t.strip()]
        out.append((ctype, name, values))
    return out


def emit_array(ctype, name, values, out):
    rust = C_TO_RUST[ctype]
    out.append(f"pub static {name}: [{rust}; {len(values)}] = [")
    line = "   "
    for v in values:
        item = f" {v},"
        if len(line) + len(item) > 99:
            out.append(line)
            line = "   "
        line += item
    out.append(line)
    out.append("];")
    out.append("")


HEADER = """// Generated by vendor/nunicode/tools/gen_tables.py from
// vendor/nunicode/src/libnu/gen/{src} of the C++ repo. Do not edit.
"""


def gen_tables(nunicode, src, dst):
    text = open(os.path.join(nunicode, "src/libnu/gen", src)).read()
    out = [HEADER.format(src=src)]
    out.append("#![allow(clippy::unreadable_literal)]")
    out.append("")
    for ctype, name, values in arrays(text):
        emit_array(ctype, name, values, out)
    open(dst, "w").write("\n".join(out))


def translate_switch_body(lines):
    """Translates the C body of `if (w != 0) { ... }` into Rust."""
    out = []
    stack = []
    for raw in lines:
        indent = raw[: len(raw) - len(raw.lstrip("\t"))].replace("\t", "    ")
        line = raw.strip()
        if not line:
            out.append("")
            continue
        m = re.fullmatch(r"(\}\s*)?(else if|if) \((.*)\) \{(\s*/\*.*\*/)?", line)
        if m:
            if m.group(1):
                kind = stack.pop()
                assert kind == "block"
            prefix = "} " if m.group(1) else ""
            out.append(f"{indent}{prefix}{m.group(2)} {m.group(3)} {{{m.group(4) or ''}")
            stack.append("block")
            continue
        m = re.fullmatch(r"(\}\s*)?else \{(\s*/\*.*\*/)?", line)
        if m:
            if m.group(1):
                kind = stack.pop()
                assert kind == "block"
            prefix = "} " if m.group(1) else ""
            out.append(f"{indent}{prefix}else {{{m.group(2) or ''}")
            stack.append("block")
            continue
        if line == "switch (u) {":
            out.append(f"{indent}match u {{")
            stack.append("match")
            continue
        m = re.fullmatch(r"case (0x[0-9A-Fa-f]+): return (0x[0-9A-Fa-f]+|state_\w+);", line)
        if m:
            out.append(f"{indent}{m.group(1)} => return {m.group(2)},")
            continue
        if line == "}":
            kind = stack.pop()
            if kind == "match":
                out.append(f"{indent}    _ => {{}}")
            out.append(f"{indent}}}")
            continue
        m = re.fullmatch(r"\*w = (\d+);", line)
        if m:
            out.append(f"{indent}*w = {m.group(1)};")
            continue
        m = re.fullmatch(r"return (0x[0-9A-Fa-f]+|state_\w+|\d+);", line)
        if m:
            out.append(f"{indent}return {m.group(1)};")
            continue
        m = re.fullmatch(r"int32_t weight = \*w;", line)
        if m:
            out.append(f"{indent}let weight: i32 = *w;")
            continue
        raise ValueError(f"untranslated C line: {raw!r}")
    assert not stack, stack
    return out


def gen_switch(nunicode, dst):
    text = open(os.path.join(nunicode, "src/libnu/gen/_ducet_switch.c")).read()
    out = [HEADER.format(src="_ducet_switch.c")]
    out.append("#![allow(non_upper_case_globals, clippy::all, clippy::pedantic)]")
    out.append("")
    out.append("use crate::udb::nu_udb_lookup_value;")
    out.append("")
    for name, value in re.findall(r"const size_t (\w+) = (\d+);", text):
        out.append(f"pub const {name}: usize = {value};")
    out.append("")
    for name, value in re.findall(r"#define (state_\w+) (-?\d+)", text):
        out.append(f"const {name}: i32 = {value};")
    out.append("")
    for ctype, name, values in arrays(text):
        emit_array(ctype, name, values, out)

    body = text[text.index("int32_t _nu_ducet_weight_switch("):]
    lines = body.split("\n")
    # Locate the re-entry block `if (w != 0) { ... }` and the final return.
    start = next(i for i, l in enumerate(lines) if l.strip().startswith("if (w != 0) {"))
    depth = 0
    end = None
    for i in range(start, len(lines)):
        depth += lines[i].count("{") - lines[i].count("}")
        if depth == 0:
            end = i
            break
    inner = lines[start + 1 : end]
    # The block opens with `int32_t weight = *w;` and `*w = 0;`.
    out.append("/// `_nu_ducet_weight_switch`: MPH lookup for root codepoints + binary")
    out.append("/// search on balanced tree for intermediate states.")
    out.append("pub fn nu_ducet_weight_switch(u: u32, w: Option<&mut i32>) -> i32 {")
    out.append("    match w {")
    out.append("        None => {")
    out.append("            // first entry, root states")
    out.append("            let state = nu_udb_lookup_value(")
    out.append("                u,")
    out.append("                &_NU_DUCET_ROOTS_G,")
    out.append("                &_NU_DUCET_ROOTS_VALUES_C,")
    out.append("                &_NU_DUCET_ROOTS_VALUES_I,")
    out.append("            );")
    out.append("")
    out.append("            if state != 0 {")
    out.append("                // VALUES_I store negated (positive) states")
    out.append("                return state.wrapping_neg() as i32;")
    out.append("            }")
    out.append("        }")
    out.append("        Some(w) => {")
    out.append("            // re-entry, intermediate states")
    for l in translate_switch_body(inner):
        out.append(("        " + l) if l else "")
    out.append("        }")
    out.append("    }")
    out.append("")
    out.append("    0")
    out.append("}")
    out.append("")
    open(dst, "w").write("\n".join(out))


def main():
    nunicode, outdir = sys.argv[1], sys.argv[2]
    for src, dst in [
        ("_ducet.c", "ducet.rs"),
        ("_tolower.c", "tolower.rs"),
        ("_toupper.c", "toupper.rs"),
        ("_tounaccent.c", "tounaccent.rs"),
    ]:
        gen_tables(nunicode, src, os.path.join(outdir, dst))
    gen_switch(nunicode, os.path.join(outdir, "ducet_switch.rs"))


if __name__ == "__main__":
    main()
